const data = $input.first().json.body || $input.first().json;

const budget = data.budget || data['custom_fields.budget'] || '';
const businessSize = data.business_size || data['custom_fields.business_size'] || '';

let score = 0;

if (budget === '$5k+') score += 40;
else if (budget === '$2k-$5k') score += 30;
else if (budget === '$500-$2k') score += 20;
else if (budget === 'Under $500') score += 5;

if (businessSize === 'Enterprise') score += 40;
else if (businessSize === 'Medium') score += 30;
else if (businessSize === 'Small') score += 20;
else if (businessSize === 'Solo') score += 10;

const leadType = score >= 60 ? 'hot' : score >= 30 ? 'warm' : 'cold';

return [{
  json: {
    first_name: data.first_name || data.firstName || '',
    last_name: data.last_name || data.lastName || '',
    email: data.email || '',
    phone: data.phone || '',
    business_type: data.business_type || '',
    business_size: businessSize,
    budget: budget,
    current_tools: data.current_tools || '',
    main_problem: data.main_problem || '',
    lead_score: score,
    lead_type: leadType,
    timestamp: new Date().toISOString()
  }
}];

